          body = {
            t = "beat",
            attribution = "cdc",
            text = {
              parts = {
                "\"Sorry. It's a DARPA thing originally, a lot of us academics communicate on it. Computer networks, that kind of thing. More free information than what you got on tv and in newspapers.\"",
