        },
        {
          line = 80,
          body = {
            t = "beat",
            attribution = "cdc",
            text = {
              parts = {
                "\"We almost didn't. There were several thousand of us in the building when the street outside swarmed. We barred the doors and headed for the Vault, but a few of us were wounded ...\"",
