          },
        },
        {
          line = 102,
          body = {
            t = "beat",
            attribution = "cdc",
            text = {
              parts = {
                "\"All of this data, and then just ... nothing. No way to get out. We've been in communication via radio with towns across the country, but one by one they've been going silent.\"",
